using System.Text;

namespace ExcelGenerator;

/// <summary>
/// LocalizationTable의 언어 컬럼으로 <c>GameData.Language</c> enum과 <c>GameData.Loc</c>을 만든다.
/// 클라는 <c>Loc.Get(row.NameLocKey)</c>로 지금 언어 문구를 읽는다. 언어 컬럼을 늘리면 enum 값이 따라 늘어난다.
/// </summary>
internal static class LocCodeGenerator
{
    public const string FileName = "Loc.cs";

    private const string Header =
        "// <auto-generated>\n" +
        "// 이 파일은 ExcelGenerator가 Localization.xlsx(LocalizationTable)의 언어 컬럼으로부터 생성했습니다. 직접 수정 금지.\n" +
        "// </auto-generated>\n\n";

    /// <summary>번역 테이블이 있으면 Loc.cs를 만들고, 없으면 옛 파일을 지운다.</summary>
    public static void Generate(IReadOnlyList<ExcelGenerator.TableData> tables, string gameDataDir)
    {
        var path  = Path.Combine(gameDataDir, FileName);
        var table = tables.FirstOrDefault(t => t.Name == Localization.TableName);
        if (table is null)
        {
            if (File.Exists(path))
            {
                File.Delete(path);
            }
            return;
        }

        // 첫 컬럼은 Key, 나머지가 언어(KR이 맨 앞 = 기본값)
        var languages = table.columnInfos.Skip(1).Select(c => c.Name).ToList();
        CodeGenUtil.WriteText(path, Header + Build(languages));
        Console.WriteLine($"[코드 생성] Loc: 언어 {string.Join("·", languages)} → GameData/{FileName}");
    }

    private static string Build(IReadOnlyList<string> languages)
    {
        var sb = new StringBuilder();
        sb.AppendLine("/// <summary>번역 언어. Localization.xlsx의 언어 컬럼 순서와 같다.</summary>");
        sb.AppendLine("public enum Language");
        sb.AppendLine("{");
        foreach (var language in languages)
        {
            sb.AppendLine($"    {language},");
        }
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/// <summary>");
        sb.AppendLine("/// 번역 문구 조회. 빈 번역은 생성 시점에 KR로 채워졌다 — 없는 키는 키를 그대로 돌려준다(화면에서 바로 보이게).");
        sb.AppendLine("/// <c>GameTable.LoadAll</c> 뒤에 읽는다.");
        sb.AppendLine("/// </summary>");
        sb.AppendLine("public static class Loc");
        sb.AppendLine("{");
        sb.AppendLine($"    public static Language Current {{ get; set; }} = Language.{languages[0]};");
        sb.AppendLine();
        sb.AppendLine("    public static string Get(string key)");
        sb.AppendLine("    {");
        sb.AppendLine("        return Get(key, Current);");
        sb.AppendLine("    }");
        sb.AppendLine();
        sb.AppendLine("    public static string Get(string key, Language language)");
        sb.AppendLine("    {");
        sb.AppendLine($"        if (!GameTable.{Localization.TableName}.TryGet(key, out var row))");
        sb.AppendLine("        {");
        sb.AppendLine("            return key;");
        sb.AppendLine("        }");
        sb.AppendLine();
        sb.AppendLine("        switch (language)");
        sb.AppendLine("        {");
        foreach (var language in languages.Skip(1))
        {
            sb.AppendLine($"            case Language.{language}: return row.{language};");
        }
        sb.AppendLine($"            default: return row.{languages[0]};");
        sb.AppendLine("        }");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return CodeGenUtil.BuildFile("GameData", Array.Empty<string>(), sb.ToString());
    }
}
